param([ValidateSet(20)][int]$Count=20)
$ErrorActionPreference='Stop'
$corpusRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$encoding=[Text.UTF8Encoding]::new($false)
function Write-PreservedText([string]$Path,[string]$Text){
    if(Test-Path -LiteralPath $Path){
        if([IO.File]::ReadAllText($Path) -cne $Text){throw "Existing fixture differs; preserve it and create a new version: $Path"}
    }else{[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($Path))|Out-Null;[IO.File]::WriteAllText($Path,$Text,$encoding)}
}
function Tile([string]$Id,[string]$Class='tile',[string]$Text=''){return '<div data-case-node="'+$Id+'" class="'+$Class+'">'+$Text+'</div>'}
$cases=@(
