    @{name='nested-overflow';family='position';features=@('overflow-hidden','nested-clip','absolute');css='.outer{width:220px;height:135px;overflow:hidden;margin:15px;background:#d9e8ee;border:3px solid #254365}.inner{position:relative;width:300px;height:180px;margin:17px;background:#479397;overflow:hidden}.tile{position:absolute;left:65px;top:40px;width:260px;height:90px;background:#d88b42}';html=('<div data-case-node="outer" class="outer"><div data-case-node="inner" class="inner">'+(Tile 'tile')+'</div></div>')},
    @{name='radius-gradient';family='paint';features=@('border-radius','gradient','border','shadow');css='.box{width:240px;height:135px;margin:25px;border:3px solid #26415c;border-radius:22px 8px;background:linear-gradient(120deg,#448c9e,#e2bd74);box-shadow:7px 9px 12px #0004}';html=(Tile 'box' 'box')},
    @{name='svg-paint';family='paint';features=@('svg','viewbox','stroke','transform');css='svg{display:block;margin:12px;background:#eef2f7}';html='<svg data-case-node="svg" width="300" height="170" viewBox="0 0 300 170"><rect x="12" y="15" width="115" height="80" fill="#4d98a1"/><circle cx="185" cy="78" r="43" fill="#d49343" stroke="#273e5a" stroke-width="4"/><path d="M20 145 L95 110 L155 145 L265 115" fill="none" stroke="#714f91" stroke-width="7"/></svg>'},
    @{name='generated-boxes';family='cascade';features=@('pseudo-element','content','absolute','cascade');css='.box{position:relative;width:230px;height:130px;margin:15px;background:#dce8ef}.box::before{content:"";display:block;width:80px;height:55px;background:#3c7b94}.box::after{content:"";position:absolute;right:14px;bottom:12px;width:90px;height:45px;background:#d38b43}';html=(Tile 'box' 'box')},
