    @{name='mixed-writing';family='text';features=@('text','korean','bidi','white-space');css='.shell{display:grid;grid-template-columns:180px 130px;gap:12px;margin:12px}.text{background:#e5edf3;padding:8px;font:15px/23px "Malgun Gothic"}.rtl{direction:rtl;background:#ecd8b9;font:16px/24px Arial;padding:8px}';html='<div data-case-node="shell" class="shell"><div data-case-node="text" class="text">한글 레이아웃 검증과 Latin text 123. 여러 줄의 문장을 비교합니다.</div><div data-case-node="rtl" class="rtl">abc 123 שלום xyz</div></div>'},
    @{name='form-initial-state';family='cascade';features=@('form','ua-style','checked','disabled');css='.form{padding:15px;display:grid;gap:12px;width:290px}input,select,button{font:14px Arial}.row{display:flex;gap:10px;align-items:center}';html='<div data-case-node="form" class="form"><input data-case-node="input" value="Static input"><select data-case-node="select"><option>First option</option><option selected>Second option</option></select><div data-case-node="row" class="row"><input data-case-node="checkbox" type="checkbox" checked><input data-case-node="disabled" type="checkbox" disabled><button data-case-node="button">Button</button></div></div>'},
    @{name='complex-dashboard';family='integration';features=@('flex','grid','table','text','absolute','clip');css='.dashboard{display:grid;grid-template-columns:72px 1fr;gap:10px;padding:10px}.sidebar{background:#263e59;min-height:330px}.main{min-width:0}.header{display:flex;justify-content:space-between;background:#dae6f0;padding:12px;margin-bottom:10px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.card{position:relative;background:#72adb2;padding:12px;min-width:0;height:85px;overflow:hidden}.card::after{content:"";position:absolute;right:-8px;bottom:-12px;width:55px;height:55px;background:#dbaa5a;border-radius:50%}.content{display:flex;gap:12px;margin-top:12px}.chart{flex:1;display:flex;gap:7px;align-items:flex-end;height:130px;background:#e6eef4;padding:10px}.bar{flex:1;background:#3a7295}.bar:nth-child(1){height:40%}.bar:nth-child(2){height:80%}.bar:nth-child(3){height:65%}.summary{width:80px;background:#d9b77e;padding:8px}';html='<div data-case-node="dashboard" class="dashboard"><aside data-case-node="sidebar" class="sidebar"></aside><main data-case-node="main" class="main"><header data-case-node="header" class="header"><span data-case-node="title">Overview</span><span data-case-node="status">Ready</span></header><section data-case-node="cards" class="cards"><div data-case-node="card1" class="card">Sales</div><div data-case-node="card2" class="card">Orders</div><div data-case-node="card3" class="card">Reports</div></section><section data-case-node="content" class="content"><div data-case-node="chart" class="chart"><div data-case-node="bar1" class="bar"></div><div data-case-node="bar2" class="bar"></div><div data-case-node="bar3" class="bar"></div></div><div data-case-node="summary" class="summary">Totals<br>123</div></section></main></div>'}
)
$manifest=@();$index=0
foreach($case in $cases){
    $index++;$id=('{0:D4}-{1}' -f $index,$case.name);$folder=Join-Path $corpusRoot ('fixtures\'+$id)
    $html='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+ $id+'</title><link rel="stylesheet" href="style.css"></head><body data-case-node="body">'+$case.html+'</body></html>'
    $css='body{margin:0;background:#fff;font:16px/20px Arial;color:#17202a}'+"`n"+$case.css+"`n"
    Write-PreservedText (Join-Path $folder 'index.html') $html
    Write-PreservedText (Join-Path $folder 'style.css') $css
    $metadata=[ordered]@{schemaVersion=1;id=$id;stage='pilot';family=$case.family;features=$case.features;seed=20261003;generatorVersion='1.0';scriptless=$true;states=@('initial');viewports=@(@(384,768),@(800,600),@(1280,800));dpi=@(96,144);htmlSha256=(Get-FileHash -LiteralPath (Join-Path $folder 'index.html') -Algorithm SHA256).Hash;cssSha256=(Get-FileHash -LiteralPath (Join-Path $folder 'style.css') -Algorithm SHA256).Hash}
    Write-PreservedText (Join-Path $folder 'case.json') (($metadata|ConvertTo-Json -Depth 8)+"`n")
    $manifest+=$metadata
}
$manifestPath=Join-Path $corpusRoot 'corpus-manifest.json'
Write-PreservedText $manifestPath (([ordered]@{schemaVersion=1;generatorVersion='1.0';seed=20261003;count=$manifest.Count;cases=$manifest}|ConvertTo-Json -Depth 10)+"`n")
Write-Output ('Preserved '+$manifest.Count+' fixtures: '+$manifestPath)
